import pytest

import junit_merge


def test_sv5ci02_compositional_02():
    r = junit_merge.merge([[{'name': 'b', 'status': 'failed', 'time': 1.5}, {'name': 'a', 'status': 'passed', 'time': 0.25}], [{'name': 'b', 'status': 'passed', 'time': 1.25}]])
    assert r['tests']['b'] == {'verdict': 'flaky', 'attempts': 2, 'time': 2.75} and r['tests']['a'] == {'verdict': 'passed', 'attempts': 1, 'time': 0.25}

